CREATE TABLE "conversations" ("id" TEXT NOT NULL,"customer_id" TEXT,"channel" TEXT NOT NULL DEFAULT 'whatsapp',"external_id" TEXT NOT NULL,"last_message_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "conversations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "conversations_external_id_key" ON "conversations"("external_id"); CREATE INDEX "conversations_customer_id_idx" ON "conversations"("customer_id"); CREATE INDEX "conversations_channel_idx" ON "conversations"("channel");
ALTER TABLE "conversations" ADD CONSTRAINT "conversations_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "conversation_messages" ("id" TEXT NOT NULL,"conversation_id" TEXT NOT NULL,"external_id" TEXT NOT NULL,"direction" TEXT NOT NULL,"message_type" TEXT NOT NULL DEFAULT 'text',"body" TEXT,"from_address" TEXT,"to_address" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "conversation_messages_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "conversation_messages_external_id_key" ON "conversation_messages"("external_id"); CREATE INDEX "conversation_messages_conversation_id_created_at_idx" ON "conversation_messages"("conversation_id","created_at");
ALTER TABLE "conversation_messages" ADD CONSTRAINT "conversation_messages_conversation_id_fkey" FOREIGN KEY ("conversation_id") REFERENCES "conversations"("id") ON DELETE CASCADE ON UPDATE CASCADE;